1: // SQL injection prevention using prepared statements\n2: // or stored procedures.\n3: //\n4: $mysqli = new mysqli($host, $user, $password, $db);\n5: if ($mysqli->connect_error) {\n6: die('Connect Error: ' . $mysqli->connect_error);\n7: }\n8: $stmt = $mysqli->prepare('INSERT INTO collection (id, name, description) VALUES (?, ?, ?)');\n9: $stmt->bind_param('sss', $id, $name, $description);\n10: $stmt->execute();\n11: $stmt->close();\n\n12: // Alternative: use a stored procedure\n13: // $mysqli->query('INSERT INTO collection (id, name, description) VALUES \n14: //   (?, ?, ?)', $id, $name, $description);\n\n